import SwiftUI

struct StepConfig {
    var value: Int = 10
    let step: Int = 5
    let maxLimit: Int = 20

    mutating func increment() {
        if value + step <= maxLimit {
            value += step
        }
    }
}

var cfg = StepConfig()
cfg.increment()
cfg.increment()
cfg.increment()
print("Value: \(cfg.value)")

