import SwiftUI

struct RegistrationForm {
    var username: String = ""
    var password: String = ""

    var isSubmitAllowed: Bool {
        return username.count >= 3 && password.count >= 6
    }
}

var form = RegistrationForm(username: "Jordan", password: "securepassword")
print("Allowed: \(form.isSubmitAllowed)")

import SwiftUI

enum AccountType: String, CaseIterable, Identifiable {
    case personal = "Personal"
    case business = "Business"
    case creator = "Creator"

    var id: String { rawValue }
}

for account in AccountType.allCases {
    print(account.id)
}

import SwiftUI

struct ProfileDraft {
    var displayName: String = ""
    var isNewsletterSubscribed: Bool = false

    mutating func reset() {
        displayName = ""
        isNewsletterSubscribed = false
    }
}

var profile = ProfileDraft(displayName: "Taylor", isNewsletterSubscribed: true)
profile.reset()
print("Name: '\(profile.displayName)', Subscribed: \(profile.isNewsletterSubscribed)")
